-- 用户授权的现有迁入工艺去重；不是再次导入旧系统数据。
-- 仅指定的已核实物理业务库执行数据调整，其他库不改业务数据。
-- 同code/name且全部节点属性、实际连接相同才合并；产品适用范围取既有并集。
-- 保留最低既有版本及其主键；不补工序、不重排版本、不合并正常/派生草稿。
-- 按一个保留版本归并一组旧版本；每组使用集合更新并独立提交。
-- 已核实前次执行296个重复版本已提交；本脚本只接受该明确状态，继续42组389个版本。
-- 来源引用每500条集合更新并返回进度，仍在同一版本组事务内提交，避免连接长期无响应。
-- 中途异常仅回滚当前组；已提交组保留，必须核实完成范围后制定恢复，不得盲目重跑。
-- 仅更正工艺/节点关联；业务事实数量、人员、时间、请求摘要及原始证据载荷不改。
SET @mes_routing_v52_old_isolation=@@transaction_isolation;
SET @mes_routing_v52_old_wait=@@innodb_lock_wait_timeout;
SET SESSION transaction_isolation='READ-COMMITTED';
SET SESSION innodb_lock_wait_timeout=10;
CREATE TEMPORARY TABLE mes_routing_v52_route (
 old_id BIGINT NOT NULL COMMENT '本次合并的重复工艺主键',
 keep_id BIGINT NOT NULL COMMENT '内容等价的保留工艺主键',
 old_version INT NOT NULL COMMENT '重复工艺原版本号',
 keep_version INT NOT NULL COMMENT '保留工艺原版本号',
 old_revision INT NOT NULL COMMENT '重复工艺预期修订号',
 keep_revision INT NOT NULL COMMENT '保留工艺预期修订号',
 code VARCHAR(64) NOT NULL COMMENT '来源已核实的工艺编码',
 name VARCHAR(255) NOT NULL COMMENT '来源已核实的工艺名称',
 PRIMARY KEY(old_id), KEY idx_v52_keep(keep_id)
) ENGINE=InnoDB COMMENT='本次升级的会话级工艺身份对应';
CREATE TEMPORARY TABLE mes_routing_v52_node (
 old_id BIGINT NOT NULL COMMENT '待合并的原节点主键',
 keep_id BIGINT NOT NULL COMMENT '位置及属性等价的保留节点主键',
 old_routing_id BIGINT NOT NULL COMMENT '原节点所属重复工艺',
 keep_routing_id BIGINT NOT NULL COMMENT '保留节点所属工艺',
 sequence_no INT NOT NULL COMMENT '由实际连接核实的节点位置',
 PRIMARY KEY(old_id), KEY idx_v52_node_route(old_routing_id)
) ENGINE=InnoDB COMMENT='本次升级的会话级等价节点对应';
CREATE TEMPORARY TABLE mes_routing_v52_order (
 id BIGINT NOT NULL COMMENT '当前批次已锁定的工单主键',
 PRIMARY KEY(id)
) ENGINE=InnoDB COMMENT='当前保留版本分组的已锁工单集合';
CREATE TEMPORARY TABLE mes_routing_v52_execution (
 id BIGINT NOT NULL COMMENT '当前批次已锁定的执行主键',
 PRIMARY KEY(id)
) ENGINE=InnoDB COMMENT='当前保留版本分组的已锁执行集合';

