CREATE TEMPORARY TABLE mes_routing_v52_batch LIKE mes_routing_v52_route;
CREATE TEMPORARY TABLE mes_routing_v52_batch_node LIKE mes_routing_v52_node;
CREATE TEMPORARY TABLE mes_routing_v52_lock (id BIGINT NOT NULL COMMENT '本组需要固定身份的工艺主键',PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE mes_routing_v52_source AS SELECT id,entity_id AS keep_id FROM mes_legacy_source_mapping WHERE 1=0;
ALTER TABLE mes_routing_v52_source ADD PRIMARY KEY(id);
CREATE TEMPORARY TABLE mes_routing_v52_source_chunk LIKE mes_routing_v52_source;
DROP PROCEDURE IF EXISTS mes_routing_v52_finish;
DROP PROCEDURE IF EXISTS mes_routing_v52_apply;
DROP PROCEDURE IF EXISTS mes_routing_v52_merge_one;
DROP PROCEDURE IF EXISTS mes_routing_v52_merge_batch;
DROP PROCEDURE IF EXISTS mes_routing_v52_assert;
DELIMITER $$
CREATE PROCEDURE mes_routing_v52_assert(IN p_old BIGINT)
BEGIN
 IF (SELECT COUNT(*) FROM mes_routing_v52_route m JOIN routing a ON a.id=m.old_id JOIN routing b ON b.id=m.keep_id
     WHERE m.old_id=p_old AND CAST(a.code AS BINARY)=CAST(m.code AS BINARY) AND CAST(b.code AS BINARY)=CAST(m.code AS BINARY)
      AND CAST(a.name AS BINARY)=CAST(m.name AS BINARY) AND CAST(b.name AS BINARY)=CAST(m.name AS BINARY)
      AND a.version=m.old_version AND b.version=m.keep_version
      AND a.revision=m.old_revision AND b.revision=m.keep_revision
      AND a.status='PUBLISHED' AND b.status='PUBLISHED')<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52工艺身份、状态或修订号发生变化';
 END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_node m LEFT JOIN routing_node a ON a.id=m.old_id LEFT JOIN routing_node b ON b.id=m.keep_id
     WHERE m.old_routing_id=p_old AND (a.id IS NULL OR b.id IS NULL
      OR a.routing_id<>m.old_routing_id OR b.routing_id<>m.keep_routing_id
      OR NOT(CAST(a.node_code AS BINARY) <=> CAST(b.node_code AS BINARY)) OR NOT(a.operation_id <=> b.operation_id)
      OR NOT(CAST(a.operation_code AS BINARY) <=> CAST(b.operation_code AS BINARY))
      OR NOT(CAST(a.operation_name AS BINARY) <=> CAST(b.operation_name AS BINARY))
      OR NOT(CAST(a.operation_description AS BINARY) <=> CAST(b.operation_description AS BINARY))
      OR NOT(a.is_key <=> b.is_key) OR NOT(CAST(a.description AS BINARY) <=> CAST(b.description AS BINARY))
      OR NOT(a.display_order <=> b.display_order))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52节点属性不同，禁止合并'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_route m WHERE m.old_id=p_old
     AND ((SELECT COUNT(*) FROM routing_node n WHERE n.routing_id=m.old_id)<>
          (SELECT COUNT(*) FROM mes_routing_v52_node n WHERE n.old_routing_id=p_old)
      OR (SELECT COUNT(*) FROM routing_node n WHERE n.routing_id=m.old_id)<>
         (SELECT COUNT(*) FROM routing_node n WHERE n.routing_id=m.keep_id)
      OR (SELECT COUNT(*) FROM routing_edge e WHERE e.routing_id=m.old_id)<>
         (SELECT COUNT(*) FROM routing_edge e WHERE e.routing_id=m.keep_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52节点或连接集合发生变化'; END IF;
 IF EXISTS(SELECT 1 FROM routing_edge e
     LEFT JOIN mes_routing_v52_node a ON a.old_id=e.from_node_id
     LEFT JOIN mes_routing_v52_node_to b ON b.old_id=e.to_node_id
     LEFT JOIN routing_edge k ON k.routing_id=a.keep_routing_id AND k.from_node_id=a.keep_id AND k.to_node_id=b.keep_id
     WHERE e.routing_id=p_old AND (a.old_id IS NULL OR b.old_id IS NULL OR k.id IS NULL
       OR a.old_routing_id<>e.routing_id OR b.old_routing_id<>e.routing_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52连接拓扑不同，禁止合并'; END IF;
END$$
CREATE PROCEDURE mes_routing_v52_merge_batch(IN p_batch INT)
batch_main: BEGIN
 DECLARE v_keep BIGINT;
 DECLARE v_id BIGINT;
 DECLARE v_old BIGINT;
 DECLARE v_last BIGINT DEFAULT 0;
 DECLARE v_count INT;
 DECLARE v_routes INT DEFAULT 0;
 DECLARE v_done BOOLEAN DEFAULT FALSE;
 DECLARE c_order CURSOR FOR SELECT w.id FROM mes_routing_v52_batch b
   STRAIGHT_JOIN workorder w FORCE INDEX(idx_workorder_routing) ON w.routing_id=b.old_id ORDER BY w.id FOR UPDATE;
 DECLARE c_execution CURSOR FOR SELECT e.id FROM mes_routing_v52_batch b
   STRAIGHT_JOIN mes_production_execution e FORCE INDEX(idx_execution_routing) ON e.routing_id=b.old_id ORDER BY e.id FOR UPDATE;
 DECLARE c_route CURSOR FOR SELECT r.id FROM mes_routing_v52_lock b STRAIGHT_JOIN routing r ON r.id=b.id ORDER BY r.id FOR UPDATE;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF DATABASE()<>'mes_base_dev_perf_test' THEN LEAVE batch_main; END IF;
 DELETE FROM mes_routing_v52_source_chunk;
 DELETE FROM mes_routing_v52_source;
 DELETE FROM mes_routing_v52_batch;
 DELETE FROM mes_routing_v52_batch_node;
 DELETE FROM mes_routing_v52_lock;
 DELETE FROM mes_routing_v52_order;
 DELETE FROM mes_routing_v52_execution;
 INSERT INTO mes_routing_v52_batch SELECT * FROM mes_routing_v52_route WHERE batch_no=p_batch;
 SELECT COUNT(*),MIN(keep_id) INTO v_count,v_keep FROM mes_routing_v52_batch;
 IF v_count=0 OR (SELECT COUNT(DISTINCT keep_id) FROM mes_routing_v52_batch)<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52分组必须对应同一个保留版本'; END IF;
 INSERT INTO mes_routing_v52_batch_node SELECT n.* FROM mes_routing_v52_node n JOIN mes_routing_v52_batch b ON b.old_id=n.old_routing_id;
 INSERT INTO mes_routing_v52_lock SELECT old_id FROM mes_routing_v52_batch;
 INSERT IGNORE INTO mes_routing_v52_lock VALUES(v_keep);
 START TRANSACTION;
 OPEN c_order;
 order_loop: LOOP
  FETCH c_order INTO v_id;
  IF v_done THEN LEAVE order_loop; END IF;
  INSERT INTO mes_routing_v52_order VALUES(v_id);
 END LOOP;
 CLOSE c_order;
 SET v_done=FALSE;
 OPEN c_execution;
 execution_loop: LOOP
  FETCH c_execution INTO v_id;
  IF v_done THEN LEAVE execution_loop; END IF;
  INSERT INTO mes_routing_v52_execution VALUES(v_id);
 END LOOP;
 CLOSE c_execution;
 SET v_done=FALSE;
 OPEN c_route;
 route_loop: LOOP
  FETCH c_route INTO v_id;
  IF v_done THEN LEAVE route_loop; END IF;
  SET v_routes=v_routes+1;
 END LOOP;
 CLOSE c_route;
 IF v_routes<>v_count+1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52工艺身份缺失'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_batch b JOIN workorder w ON w.routing_id=b.old_id LEFT JOIN mes_routing_v52_order x ON x.id=w.id WHERE x.id IS NULL) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52加锁期间工单引用改变'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_batch b JOIN mes_production_execution e ON e.routing_id=b.old_id LEFT JOIN mes_routing_v52_execution x ON x.id=e.id WHERE x.id IS NULL) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52加锁期间执行引用改变'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x JOIN mes_production_execution e ON e.id=x.id LEFT JOIN mes_routing_v52_order w ON w.id=e.workorder_id WHERE w.id IS NULL) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52执行父单不属于本组'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_order x JOIN workorder w ON w.id=x.id WHERE NOT(w.source <=> 'LOCAL')) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52本组出现非LOCAL工单'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x JOIN mes_quality_release q ON q.execution_id=x.id) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在正式质量放行，不改写冻结依据'; END IF;
 SELECT MIN(old_id) INTO v_old FROM mes_routing_v52_batch;
 WHILE v_old IS NOT NULL DO
  CALL mes_routing_v52_assert(v_old);
  SET v_last=v_old;
  SELECT MIN(old_id) INTO v_old FROM mes_routing_v52_batch WHERE old_id>v_last;
 END WHILE;
 -- 每张事实表每组只做一次集合更新，使用执行主键索引定位，避免按节点扫描整表。
 UPDATE mes_routing_v52_execution x STRAIGHT_JOIN mes_execution_path_node t FORCE INDEX(idx_execution_path_order) ON t.execution_id=x.id
 STRAIGHT_JOIN mes_routing_v52_batch_node n ON n.old_id=t.routing_node_id SET t.routing_node_id=n.keep_id;
 SET @mes_v52_mes_execution_path_node=COALESCE(@mes_v52_mes_execution_path_node,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_execution x STRAIGHT_JOIN mes_production_report t FORCE INDEX(idx_report_execution_node) ON t.execution_id=x.id
 STRAIGHT_JOIN mes_routing_v52_batch_node n ON n.old_id=t.routing_node_id SET t.routing_node_id=n.keep_id;
 SET @mes_v52_mes_production_report=COALESCE(@mes_v52_mes_production_report,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_execution x STRAIGHT_JOIN mes_production_defect t FORCE INDEX(idx_defect_execution_node) ON t.execution_id=x.id
 STRAIGHT_JOIN mes_routing_v52_batch_node n ON n.old_id=t.affected_node_id SET t.affected_node_id=n.keep_id;
 SET @mes_v52_mes_production_defect=COALESCE(@mes_v52_mes_production_defect,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_execution x STRAIGHT_JOIN mes_quality_treatment t FORCE INDEX(idx_quality_treatment_execution) ON t.execution_id=x.id
 STRAIGHT_JOIN mes_routing_v52_batch_node n ON n.old_id=t.routing_node_id SET t.routing_node_id=n.keep_id;
 SET @mes_v52_mes_quality_treatment=COALESCE(@mes_v52_mes_quality_treatment,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_execution x STRAIGHT_JOIN mes_execution_path t ON t.id=x.id
 SET t.routing_id=v_keep WHERE t.routing_id IN (SELECT old_id FROM mes_routing_v52_batch);
 SET @mes_v52_paths=COALESCE(@mes_v52_paths,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_batch b STRAIGHT_JOIN mes_production_execution t FORCE INDEX(idx_execution_routing) ON t.routing_id=b.old_id SET t.routing_id=v_keep;
 SET @mes_v52_executions=COALESCE(@mes_v52_executions,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 UPDATE mes_routing_v52_batch b STRAIGHT_JOIN workorder t FORCE INDEX(idx_workorder_routing) ON t.routing_id=b.old_id SET t.routing_id=v_keep;
 SET @mes_v52_workorders=COALESCE(@mes_v52_workorders,0)+ROW_COUNT();
 SELECT p_batch AS merge_group,'FACT_REFERENCES' AS phase;
 INSERT INTO mes_routing_v52_source SELECT t.id,b.keep_id FROM mes_routing_v52_batch b STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='ROUTING' AND t.entity_id=b.old_id;
 INSERT INTO mes_routing_v52_source SELECT t.id,b.keep_id FROM mes_routing_v52_batch b STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='ROUTING_IDENTITY_RESTORE' AND t.entity_id=b.old_id;
 INSERT INTO mes_routing_v52_source SELECT t.id,b.keep_id FROM mes_routing_v52_batch_node b STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='NODE' AND t.entity_id=b.old_id;
 INSERT INTO mes_routing_v52_source SELECT t.id,b.keep_id FROM mes_routing_v52_batch_node b STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='NODE_QUALITY_CONVERSION' AND t.entity_id=b.old_id;
 -- 先经覆盖索引汇总来源记录主键，再按临时表聚簇主键访问大表，减少随机回表读取JSON所在数据页。
 -- 500条一批，组内不提交；逐批返回轻量进度，避免长CALL无网络响应。
 WHILE EXISTS(SELECT 1 FROM mes_routing_v52_source LIMIT 1) DO
  DELETE FROM mes_routing_v52_source_chunk;
  INSERT INTO mes_routing_v52_source_chunk SELECT * FROM mes_routing_v52_source ORDER BY id LIMIT 500;
  UPDATE mes_routing_v52_source_chunk x STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(PRIMARY) ON t.id=x.id SET t.entity_id=x.keep_id;
  SELECT p_batch AS merge_group,'SOURCE_REFERENCES' AS phase,ROW_COUNT() AS updated_rows;
  DELETE t FROM mes_routing_v52_source_chunk x STRAIGHT_JOIN mes_routing_v52_source t ON t.id=x.id;
 END WHILE;
 -- 本组所有旧版本产品范围取并集；同产品只插入一次，原有保留版本的快照不覆盖。
 INSERT INTO routing_product(routing_id,material_id,material_code,material_name)
 SELECT v_keep,p.material_id,MIN(p.material_code),MIN(p.material_name)
 FROM mes_routing_v52_batch b JOIN routing_product p ON p.routing_id=b.old_id
 LEFT JOIN routing_product k ON k.routing_id=v_keep AND k.material_id=p.material_id
 WHERE k.id IS NULL GROUP BY p.material_id;
 SET @mes_v52_products_added=COALESCE(@mes_v52_products_added,0)+ROW_COUNT();
 IF EXISTS(SELECT 1 FROM mes_routing_v52_order x JOIN workorder w ON w.id=x.id LEFT JOIN routing_product p ON p.routing_id=w.routing_id AND p.material_id=w.product_id WHERE w.routing_id<>v_keep OR p.id IS NULL) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52工单关联验证失败'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x JOIN mes_production_execution e ON e.id=x.id LEFT JOIN mes_execution_path p ON p.id=e.id WHERE e.routing_id<>v_keep OR (p.id IS NOT NULL AND p.routing_id<>v_keep)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52执行路径关联验证失败'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x STRAIGHT_JOIN mes_execution_path_node t FORCE INDEX(idx_execution_path_order) ON t.execution_id=x.id
 LEFT JOIN routing_node n ON n.id=t.routing_node_id WHERE n.id IS NULL OR n.routing_id<>v_keep) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52事实节点归属验证失败'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x STRAIGHT_JOIN mes_production_report t FORCE INDEX(idx_report_execution_node) ON t.execution_id=x.id
 LEFT JOIN routing_node n ON n.id=t.routing_node_id WHERE n.id IS NULL OR n.routing_id<>v_keep) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52事实节点归属验证失败'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x STRAIGHT_JOIN mes_production_defect t FORCE INDEX(idx_defect_execution_node) ON t.execution_id=x.id
 LEFT JOIN routing_node n ON n.id=t.affected_node_id WHERE n.id IS NULL OR n.routing_id<>v_keep) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52事实节点归属验证失败'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_execution x STRAIGHT_JOIN mes_quality_treatment t FORCE INDEX(idx_quality_treatment_execution) ON t.execution_id=x.id
 LEFT JOIN routing_node n ON n.id=t.routing_node_id WHERE n.id IS NULL OR n.routing_id<>v_keep) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52事实节点归属验证失败'; END IF;
 DELETE t FROM mes_routing_v52_batch b STRAIGHT_JOIN routing_edge t ON t.routing_id=b.old_id;
 DELETE t FROM mes_routing_v52_batch b STRAIGHT_JOIN routing_product t ON t.routing_id=b.old_id;
 DELETE t FROM mes_routing_v52_batch b STRAIGHT_JOIN routing_node t ON t.routing_id=b.old_id;
 DELETE t FROM mes_routing_v52_batch b STRAIGHT_JOIN routing t ON t.id=b.old_id;
 IF ROW_COUNT()<>v_count THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52本组删除版本数异常'; END IF;
 COMMIT;
 SET @mes_v52_completed=@mes_v52_completed+1;
 SELECT p_batch AS merge_group,'COMMITTED' AS phase;
END$$
CREATE PROCEDURE mes_routing_v52_apply()
main: BEGIN
 DECLARE v_old BIGINT;
 DECLARE v_last BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF DATABASE()<>'mes_base_dev_perf_test' THEN LEAVE main; END IF;
 IF @@server_uuid<>'03dbc952-7403-11ef-802c-0242ac130002' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52目标物理数据库身份不一致';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE())<>0
 OR (SELECT COUNT(*) FROM flyway_business_schema_history WHERE version='51' AND success=1)<>1
 OR (SELECT COUNT(*) FROM mes_routing_v52_route)<>685
 OR (SELECT COUNT(*) FROM mes_routing_v52_node)<>7875 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52前置版本、触发器或计划范围不一致';
 END IF;
 IF (SELECT COUNT(*) FROM mes_routing_v52_route m JOIN routing r ON r.id=m.old_id)<>389 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在已完成或缺失对象，禁止盲目重跑';
 END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_route r JOIN workorder w ON w.routing_id=r.old_id WHERE NOT(w.source <=> 'LOCAL')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52发现来源、父单或冻结指令冲突，未开始合并'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_route r JOIN mes_production_execution e ON e.routing_id=r.old_id
     LEFT JOIN workorder w ON w.id=e.workorder_id WHERE w.id IS NULL OR w.routing_id<>e.routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52发现来源、父单或冻结指令冲突，未开始合并'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_route r JOIN mes_material_issue i ON i.routing_id=r.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52发现来源、父单或冻结指令冲突，未开始合并'; END IF;
IF EXISTS(SELECT 1 FROM mes_execution_assignment a JOIN mes_routing_v52_node n ON n.old_id=a.routing_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52发现来源、父单或冻结指令冲突，未开始合并'; END IF;
IF EXISTS(SELECT 1 FROM batch_route_node a JOIN mes_routing_v52_node n ON n.old_id=a.routing_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52发现来源、父单或冻结指令冲突，未开始合并'; END IF;
 IF EXISTS(SELECT 1 FROM mes_routing_v52_route m LEFT JOIN routing r ON r.id=m.old_id WHERE (m.batch_no=0 AND r.id IS NOT NULL) OR (m.batch_no>0 AND r.id IS NULL)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52停止范围与已核实的296版本不一致'; END IF;
 -- 在任何版本提交之前核实整份计划及原事实节点归属。
 SELECT MIN(old_id) INTO v_old FROM mes_routing_v52_route WHERE batch_no>0;
 WHILE v_old IS NOT NULL DO
  CALL mes_routing_v52_assert(v_old);
  SET v_last=v_old;
  SELECT MIN(old_id) INTO v_old FROM mes_routing_v52_route WHERE old_id>v_last AND batch_no>0;
 END WHILE;

IF EXISTS(SELECT 1 FROM mes_execution_path_node t JOIN mes_routing_v52_node n ON n.old_id=t.routing_node_id
 LEFT JOIN mes_production_execution e ON e.id=t.execution_id WHERE e.id IS NULL OR e.routing_id<>n.old_routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52原mes_execution_path_node节点归属异常'; END IF;

IF EXISTS(SELECT 1 FROM mes_production_report t JOIN mes_routing_v52_node n ON n.old_id=t.routing_node_id
 LEFT JOIN mes_production_execution e ON e.id=t.execution_id WHERE e.id IS NULL OR e.routing_id<>n.old_routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52原mes_production_report节点归属异常'; END IF;

IF EXISTS(SELECT 1 FROM mes_production_defect t JOIN mes_routing_v52_node n ON n.old_id=t.affected_node_id
 LEFT JOIN mes_production_execution e ON e.id=t.execution_id WHERE e.id IS NULL OR e.routing_id<>n.old_routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52原mes_production_defect节点归属异常'; END IF;

IF EXISTS(SELECT 1 FROM mes_quality_treatment t JOIN mes_routing_v52_node n ON n.old_id=t.routing_node_id
 LEFT JOIN mes_production_execution e ON e.id=t.execution_id WHERE e.id IS NULL OR e.routing_id<>n.old_routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52原mes_quality_treatment节点归属异常'; END IF;

IF EXISTS(SELECT 1 FROM mes_routing_v52_route r JOIN mes_production_execution e ON e.routing_id=r.old_id
 JOIN mes_quality_release q ON q.execution_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在正式放行，未开始合并'; END IF;
 SET @mes_v52_completed=0;
END$$
CREATE PROCEDURE mes_routing_v52_finish()
finish_main: BEGIN
 IF DATABASE()<>'mes_base_dev_perf_test' THEN LEAVE finish_main; END IF;
 IF NOT(@mes_v52_completed <=> 42) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52完成版本数异常'; END IF;
 IF EXISTS(SELECT 1 FROM workorder t JOIN mes_routing_v52_route m ON m.old_id=t.routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_production_execution t JOIN mes_routing_v52_route m ON m.old_id=t.routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_execution_path t JOIN mes_routing_v52_route m ON m.old_id=t.routing_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_execution_path_node t JOIN mes_routing_v52_node m ON m.old_id=t.routing_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_production_report t JOIN mes_routing_v52_node m ON m.old_id=t.routing_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_production_defect t JOIN mes_routing_v52_node m ON m.old_id=t.affected_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_quality_treatment t JOIN mes_routing_v52_node m ON m.old_id=t.routing_node_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM routing t JOIN mes_routing_v52_route m ON m.old_id=t.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_route m STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='ROUTING' AND t.entity_id=m.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_route m STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='ROUTING_IDENTITY_RESTORE' AND t.entity_id=m.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_node m STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='NODE' AND t.entity_id=m.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
IF EXISTS(SELECT 1 FROM mes_routing_v52_node m STRAIGHT_JOIN mes_legacy_source_mapping t FORCE INDEX(idx_legacy_target) ON t.entity_kind='NODE_QUALITY_CONVERSION' AND t.entity_id=m.old_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V52存在未订正引用'; END IF;
END$$
CALL mes_routing_v52_apply()$$
CALL mes_routing_v52_merge_batch(1)$$
CALL mes_routing_v52_merge_batch(2)$$
CALL mes_routing_v52_merge_batch(3)$$
CALL mes_routing_v52_merge_batch(4)$$
CALL mes_routing_v52_merge_batch(5)$$
